  b27: {"en": {"i": ["2 slices brioche bread (70 g)", "1 large egg (50 g)", "80 ml low-fat milk", "5 g butter", "5 g sugar", "1 g cinnamon", "50 g strawberries"], "s": ["Whisk egg, milk, sugar, and cinnamon in a shallow bowl.", "Dip bread for 10 seconds per side.", "Melt butter in a non-stick pan over medium heat.", "Cook bread 2 to 3 minutes per side until golden.", "Serve with sliced strawberries."]}, "ar": {"i": ["2 شريحة عيش بريوش (70 جم)", "1 بيضة كبيرة (50 جم)", "80 مل لبن قليل الدسم", "5 جم زبدة", "5 جم سكر", "1 جم قرفة", "50 جم فراولة"], "s": ["اخفق البيضة واللبن والسكر والقرفة في طبق واسع.", "اغمس العيش 10 ثواني لكل ناحية.", "سيّح الزبدة في طاسة نون ستك على نار متوسطة.", "اطبخ العيش 2 لـ3 دقايق لكل ناحية.", "قدّمه مع الفراولة."]}},
  b28: {"en": {"i": ["2 large eggs (100 g)", "60 g egg whites", "100 g zucchini", "50 g onion", "10 g parmesan", "5 ml olive oil", "1 g black pepper"], "s": ["Preheat oven to 190°C.", "Sauté onion and zucchini in oil for 6 minutes.", "Whisk eggs, egg whites, pepper, and parmesan and pour over vegetables.", "Cook on the stove 2 minutes, then bake 8 to 10 minutes until set.", "Rest for 2 minutes before slicing."]}, "ar": {"i": ["2 بيضة كبيرة (100 جم)", "60 جم بياض بيض", "100 جم كوسة", "50 جم بصل", "10 جم بارميزان", "5 مل زيت زيتون", "1 جم فلفل أسود"], "s": ["سخّن الفرن على 190 درجة.", "شوّح البصل والكوسة في الزيت 6 دقايق.", "اخفق البيض وبياض البيض والفلفل والبارميزان وصبهم على الخضار.", "سوّيها على البوتاجاز دقيقتين وبعدين اخبزها 8 لـ10 دقايق.", "سيبها دقيقتين قبل التقطيع."]}},
  b29: {"en": {"i": ["60 g halal halloumi", "70 g whole-wheat bread", "80 g tomato", "20 g lettuce", "3 ml olive oil"], "s": ["Slice halloumi and tomato.", "Heat oil in a grill pan over medium heat.", "Grill halloumi for 2 minutes per side.", "Warm bread for 1 minute and fill with halloumi, tomato, and lettuce."]}, "ar": {"i": ["60 جم جبنة حلومي حلال", "70 جم عيش قمح كامل", "80 جم طماطم", "20 جم خس", "3 مل زيت زيتون"], "s": ["قطّع الحلومي والطماطم.", "سخّن الزيت في طاسة جريل على نار متوسطة.", "اشوي الحلومي دقيقتين لكل ناحية.", "سخّن العيش دقيقة واحشيه بالحلومي والطماطم والخس."]}},
  b30: {"en": {"i": ["23 g whey protein powder", "1 large egg (50 g)", "30 g whole-wheat flour", "60 ml skim milk", "3 g baking powder", "5 g vegetable oil", "10 g Greek yogurt"], "s": ["Whisk all ingredients into a smooth batter.", "Preheat waffle iron and grease lightly.", "Pour in batter and cook for 4 to 5 minutes until crisp.", "Remove carefully and serve warm."]}, "ar": {"i": ["23 جم بودرة بروتين واي", "1 بيضة كبيرة (50 جم)", "30 جم دقيق قمح كامل", "60 مل لبن خالي الدسم", "3 جم بيكنج بودر", "5 جم زيت نباتي", "10 جم زبادي يوناني"], "s": ["اخفق كل المكونات لحد ما يبقوا خليط ناعم.", "سخّن جهاز الوافل وادهنه خفيف.", "صب الخليط واطبخه 4 لـ5 دقايق لحد ما يقرمش.", "طلّعه بحرص وقدّمه دافي."]}},
  b31: {"en": {"i": ["1 halal granola bar (40 g)", "180 ml low-fat milk", "1 g almonds"], "s": ["Warm the granola bar in a 180°C oven for 3 minutes.", "Pour the milk into a glass.", "Serve the warm bar with milk and almonds."]}, "ar": {"i": ["1 جرانولا بار حلال (40 جم)", "180 مل لبن قليل الدسم", "1 جم لوز"], "s": ["سخّن الجرانولا بار في فرن على 180 درجة 3 دقايق.", "صب اللبن في كوباية.", "قدّم البار الدافي مع اللبن واللوز."]}},
  b32: {"en": {"i": ["100 g halal lean beef sausage", "2 large eggs (100 g)", "5 ml olive oil", "1 g black pepper", "1 g paprika"], "s": ["Slice sausage into coins.", "Brown it in oil over medium heat for 5 to 6 minutes.", "Whisk eggs with pepper and paprika and pour into the pan.", "Cook for 3 to 4 minutes until eggs are set."]}, "ar": {"i": ["100 جم سجق بقري حلال قليل الدسم", "2 بيضة كبيرة (100 جم)", "5 مل زيت زيتون", "1 جم فلفل أسود", "1 جم بابريكا"], "s": ["قطّع السجق حلقات.", "حمّره في الزيت على نار متوسطة 5 لـ6 دقايق.", "اخفق البيض مع الفلفل والبابريكا وصبه في الطاسة.", "اطبخه 3 لـ4 دقايق لحد ما يستوي."]}},
  b33: {"en": {"i": ["1 large whole-wheat tortilla (70 g)", "1 large egg (50 g)", "30 g shredded cheddar", "30 g black beans", "2 ml olive oil", "20 g salsa"], "s": ["Whisk egg and cook in oil over medium heat for 2 minutes.", "Place tortilla in a dry skillet and add egg, beans, cheese, and salsa.", "Fold in half and cook 2 minutes per side until crisp.", "Cut into wedges and serve."]}, "ar": {"i": ["1 تورتيلا قمح كامل كبيرة (70 جم)", "1 بيضة كبيرة (50 جم)", "30 جم جبنة شيدر مبشورة", "30 جم فاصوليا سودا", "2 مل زيت زيتون", "20 جم سالسا"], "s": ["اخفق البيضة واطبخها في الزيت على نار متوسطة دقيقتين.", "حط التورتيلا في طاسة ناشفة وحط البيض والفاصوليا والجبنة والسالسا.", "اطويها نصين واطبخها دقيقتين لكل ناحية لحد ما تقرمش.", "قطّعها مثلثات وقدّمها."]}},
  b34: {"en": {"i": ["180 g mango flesh", "130 g low-fat Greek yogurt", "10 g honey", "1 g ground cardamom", "20 g granola"], "s": ["Dice mango and reserve 30 g for topping.", "Blend remaining mango with yogurt, honey, and cardamom.", "Pour into a bowl and top with reserved mango.", "Sprinkle granola and serve chilled."]}, "ar": {"i": ["180 جم لب مانجا", "130 جم زبادي يوناني قليل الدسم", "10 جم عسل", "1 جم حبهان مطحون", "20 جم جرانولا"], "s": ["قطّع المانجا وسيب 30 جم للوش.", "اضرب باقي المانجا مع الزبادي والعسل والحبهان.", "صب الخليط في بولة وحط المانجا اللي اتسابِت.", "رش الجرانولا وقدّمها ساقعة."]}},
  b35: {"en": {"i": ["180 g canned baked beans in tomato sauce", "2 slices whole-wheat toast (60 g)", "2 g butter", "1 g black pepper"], "s": ["Toast bread for 2 minutes.", "Warm beans in a saucepan over medium-low heat for 5 minutes.", "Butter toast lightly and spoon hot beans over it.", "Season with pepper and serve."]}, "ar": {"i": ["180 جم فاصوليا بيضا بالصلصة", "2 شريحة توست قمح كامل (60 جم)", "2 جم زبدة", "1 جم فلفل أسود"], "s": ["حمّص العيش دقيقتين.", "سخّن الفاصوليا في حلة على نار متوسطة هادية 5 دقايق.", "ادهن التوست بالزبدة وحط الفاصوليا السخنة فوقه.", "حط الفلفل وقدّمها."]}},
