  b51: {"en": {"i": ["50 g reduced-fat feta cheese", "300 g watermelon", "5 ml olive oil", "5 g mint", "5 ml lemon juice", "5 g honey"], "s": ["Cut watermelon and feta into bite-size cubes.", "Arrange them in a bowl with mint.", "Drizzle with lemon juice and olive oil and add honey.", "Chill for 10 minutes and serve."]}, "ar": {"i": ["50 جم جبنة فيتا قليلة الدسم", "300 جم بطيخ", "5 مل زيت زيتون", "5 جم نعناع", "5 مل عصير ليمون", "5 جم عسل"], "s": ["قطّع البطيخ والفيتا مكعبات صغيرة.", "رصهم في بولة مع النعناع.", "رش عصير الليمون وزيت الزيتون وحط العسل.", "حطها في التلاجة 10 دقايق وقدّمها."]}},
  b52: {"en": {"i": ["2 large eggs (100 g)", "180 g tomatoes", "60 g green pepper", "40 g onion", "10 ml olive oil", "1 g paprika", "1 g salt"], "s": ["Dice tomatoes, pepper, and onion.", "Cook onion and pepper in oil over medium heat for 5 minutes.", "Add tomatoes, paprika, and salt and simmer 6 minutes.", "Beat eggs, pour in, and stir gently 3 to 4 minutes until set.", "Serve hot."]}, "ar": {"i": ["2 بيضة كبيرة (100 جم)", "180 جم طماطم", "60 جم فلفل أخضر", "40 جم بصل", "10 مل زيت زيتون", "1 جم بابريكا", "1 جم ملح"], "s": ["قطّع الطماطم والفلفل والبصل مكعبات.", "اطبخ البصل والفلفل في الزيت على نار متوسطة 5 دقايق.", "حط الطماطم والبابريكا والملح وسيبهم 6 دقايق.", "اخفق البيض وصبه وقلّب 3 لـ4 دقايق لحد ما يستوي.", "قدّمه سخن."]}},
  b53: {"en": {"i": ["70 g avocado flesh", "45 g halal beef bacon", "2 large eggs (100 g)", "1 g black pepper"], "s": ["Cook sliced beef bacon in a non-stick pan over medium heat for 4 to 5 minutes.", "Set bacon aside and leave the pan lightly greased.", "Fry eggs for 3 to 4 minutes until whites set.", "Serve eggs with avocado and beef bacon and season with pepper."]}, "ar": {"i": ["70 جم لب أفوكادو", "45 جم بيكون بقري حلال", "2 بيضة كبيرة (100 جم)", "1 جم فلفل أسود"], "s": ["اطبخ البيكون البقري المتقطع في طاسة نون ستك على نار متوسطة 4 لـ5 دقايق.", "طلّع البيكون وسيب الطاسة مدهونة خفيف.", "اقلي البيض 3 لـ4 دقايق لحد ما البياض يستوي.", "قدّم البيض مع الأفوكادو والبيكون وحط الفلفل."]}},
  b54: {"en": {"i": ["40 g rolled oats", "150 ml skim milk", "10 g unsweetened cocoa powder", "70 g banana", "5 g honey", "7 g peanut butter"], "s": ["Mash half the banana and slice the rest.", "Cook oats, milk, cocoa, and mashed banana over low heat for 5 minutes.", "Stir in honey and transfer to a bowl.", "Top with banana slices and peanut butter."]}, "ar": {"i": ["40 جم شوفان", "150 مل لبن خالي الدسم", "10 جم كاكاو من غير سكر", "70 جم موز", "5 جم عسل", "7 جم زبدة فول سوداني"], "s": ["اهرِس نص الموز وقطّع الباقي.", "اطبخ الشوفان واللبن والكاكاو والموز المهروس على نار هادية 5 دقايق.", "قلّب العسل وحط الخليط في بولة.", "حط شرايح الموز وزبدة الفول السوداني على الوش."]}},
  b55: {"en": {"i": ["1 small whole-wheat pita (60 g)", "1 large egg (50 g)", "35 g shredded mozzarella", "50 g tomato", "20 g bell pepper", "5 ml olive oil", "1 g oregano"], "s": ["Preheat oven to 200°C and place pita on a tray.", "Brush pita with oil and add tomato and pepper.", "Crack egg in the center and sprinkle mozzarella and oregano.", "Bake 10 to 12 minutes until egg white sets and cheese melts.", "Cool for 2 minutes and slice."]}, "ar": {"i": ["1 عيش شامي قمح كامل صغير (60 جم)", "1 بيضة كبيرة (50 جم)", "35 جم موتزاريلا مبشورة", "50 جم طماطم", "20 جم فلفل ألوان", "5 مل زيت زيتون", "1 جم أوريجانو"], "s": ["سخّن الفرن على 200 درجة وحط العيش على صينية.", "ادهن العيش بالزيت وحط الطماطم والفلفل.", "اكسر البيضة في النص ورش الموتزاريلا والأوريجانو.", "اخبزها 10 لـ12 دقيقة لحد ما البياض يستوي والجبنة تسيح.", "سيبها دقيقتين وقطّعها."]}},
